// The API's shape is not our shape. Keep the reshape in ONE place so the
// rest of the app never sees the wire format.
async function loadActiveUsers(fetchImpl, url) {
  const res = await fetchImpl(url);
  // fetch does NOT reject on 404/500 -- only on network failure. Guard it.
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  // Reading the body is a SECOND await: the first resolved on headers alone.
  const body = await res.json();
  return body.results
    .filter(u => u.active)
    .map(u => ({
      id: u.id,
      fullName: `${u.name.first} ${u.name.last}`,
      city: u.location?.city ?? 'unknown',
      tagCount: u.tags?.length ?? 0,
    }))
    .sort((a, b) => b.tagCount - a.tagCount);
}

// Stubbed transports -- the same injected-dependency trick the debounce
// lesson uses for its clock, so the drill runs without a network.
const PAYLOAD = {
  results: [
    { id: 1, active: true, name: { first: 'Ada', last: 'Lovelace' }, location: { city: 'London' }, tags: ['math', 'logic'] },
    { id: 2, active: false, name: { first: 'Alan', last: 'Turing' }, location: { city: 'Wilmslow' }, tags: ['crypto'] },
    { id: 3, active: true, name: { first: 'Grace', last: 'Hopper' }, location: { city: 'New York' }, tags: ['compilers', 'navy', 'cobol'] },
    { id: 4, active: true, name: { first: 'Linus', last: 'Torvalds' } },
  ],
};
const okFetch = async () => ({ ok: true, status: 200, json: async () => PAYLOAD });
const downFetch = async () => ({ ok: false, status: 503, json: async () => ({}) });

(async () => {
  const rows = await loadActiveUsers(okFetch, '/api/users');
  for (const r of rows) {
    console.log(`${r.id} ${r.fullName} - ${r.city} (${r.tagCount} tags)`);
  }
  try {
    await loadActiveUsers(downFetch, '/api/users');
  } catch (err) {
    console.log(`caught: ${err.message}`);
  }
})();
